'use strict';
// Extend the existing router, SVG and language state. Business data and geometry are unchanged.
const V27={svg:'http://www.w3.org/2000/svg',mapFilters:{customer:'',state:'',lot:''},mapRows:[],
 text(g,x,y,value,css,anchor='start',business=false){const t=document.createElementNS(this.svg,'text');t.setAttribute('x',x);t.setAttribute('y',y);t.setAttribute('text-anchor',anchor);t.setAttribute('class',css);if(business)t.setAttribute('data-no-i18n','');t.textContent=value;g.append(t);return t;},
 fit(){if(typeof MapView!=='undefined')return MapView.fit();const svg=$('stock-map-svg');if(!svg)return;StockMap.zoom=1;StockMap.viewRegion=null;svg.setAttribute('width','100%');svg.style.transform='';svg.style.transformOrigin='center';if(StockMap.data.layout.width)svg.setAttribute('viewBox',`0 0 ${StockMap.data.layout.width} ${StockMap.data.layout.height}`);},
 highlight(){for(const g of document.querySelectorAll('[data-map-cell]')){const l=StockMap.data.locations.find(l=>l.cell_code===g.dataset.mapCell);if(!l)continue;const customers=[...(l.current.customers||[]),...StockMap.data.planning.filter(p=>p.planned_location_id===l.id).map(p=>({id:p.customer_id}))],state=l.allocation_state||l.state,lot=l.claim_lot_no||'';const match=(!this.mapFilters.customer||customers.some(c=>c.id===this.mapFilters.customer))&&(!this.mapFilters.state||(this.mapFilters.state==='PREPARATION_LOCKED'?Number(l.current.preparation_locked_count)>0||!!l.claim_lot_no&&['PLANNED','OCCUPIED'].includes(l.allocation_state)&&!Number(l.current.loading_plan_locked_count):this.mapFilters.state==='LOADING_ASSIGNED'?Number(l.current.loading_plan_locked_count)>0:state===this.mapFilters.state))&&(!this.mapFilters.lot||lot.toLowerCase().includes(this.mapFilters.lot.toLowerCase()));g.classList.toggle('map-dimmed',!match);g.dataset.v27Match=String(match);}},
 async mapTools(){const toolbar=MapView.mount();if(!toolbar)return;
 const filters=document.createElement('div');filters.className='v27-map-filter';filters.innerHTML=`<label>客户高亮<select id="v27-map-customer"><option value="">全部</option>${[...new Map([...StockMap.data.locations.flatMap(l=>l.current.customers),...StockMap.data.planning.map(p=>({id:p.customer_id,name:p.customer}))].map(c=>[c.id,c])).values()].map(c=>`<option data-no-i18n value="${c.id}">${esc(c.name)}</option>`).join('')}</select></label><label>货位状态<select id="v27-map-state"><option value="">全部</option>${[['PREPARATION_LOCKED','备货锁定'],['LOADING_ASSIGNED','匹配锁定']].map(([key,label])=>`<option value="${key}">${label}</option>`).join('')}</select></label><label>Lot编号定位<input id="v27-map-lot" maxlength="80"></label>`;toolbar.after(filters);for(const [id,key] of [['v27-map-customer','customer'],['v27-map-state','state'],['v27-map-lot','lot']]){const el=$(id);el.value=this.mapFilters[key];el.oninput=()=>{this.mapFilters[key]=el.value;this.highlight();};}this.fit();this.highlight();

 }
};
const v27MapDraw=StockMap.draw.bind(StockMap);
StockMap.draw=function(){v27MapDraw();const svg=$('stock-map-svg');if(!svg)return;for(const feature of svg.querySelectorAll('.map-feature')){if(!feature.classList.contains('map-feature-occupied'))feature.remove();}svg.querySelectorAll('.map-region-title').forEach(t=>{if(t.textContent==='P5')t.remove();});for(const cell of this.data.cells){const g=svg.querySelector(`[data-map-cell="${cell.code}"]`),l=this.data.locations.find(l=>l.cell_code===cell.code);if(!g||!l)continue;const x=Number(cell.x),y=Number(cell.y),w=Number(cell.width),h=Number(cell.height),temporary=l.map_usage==='TEMPORARY',plan=this.data.planning.find(p=>p.planned_location_id===l.id),customer=plan?.customer||l.current.customers[0]?.name||'',lot=l.claim_lot_no||'';g.querySelectorAll('text').forEach(t=>t.remove());if(temporary){g.classList.add('map-public-p5');V27.text(g,x+w/2,y+h*.45,'临时堆存区','v27-temporary-title','middle');V27.text(g,x+w/2,y+h*.65,String(l.current.bundle_count)+' 捆','v27-temporary-count','middle');g.querySelector('title').textContent='临时堆存区';g.setAttribute('aria-label','临时堆存区');}else{V27.text(g,x+5,y+h*.65,l.code,'map-code','start',true);if(customer||lot){const start=x+w*.3;V27.text(g,start,y+h*.44,customer.length>26?customer.slice(0,24)+'…':customer,'v27-customer','start',true);V27.text(g,start,y+h*.88,lot,'v27-lot','start',true);g.querySelector('title').textContent=[l.code,customer,lot,l.current.bundle_count].join(' · ');}else V27.text(g,x+w*.5,y+h*.65,l.current.bundle_count+' 捆','map-count','middle');}}V27.highlight();};
StockMap.metrics=function(){const o=this.data.occupancy;$('stock-map-metrics').classList.add('v27-map-summary');$('stock-map-metrics').innerHTML=[['正式货位总数',o.formal_slots],['已占用正式货位数',o.occupied_locations],['空闲正式货位数',o.empty_locations]].map(([label,n])=>`<article class="map-metric panel"><span>${label}</span>${UI.number(n??'—','个')}</article>`).join('');};
const v27MapOpen=StockMap.open.bind(StockMap);StockMap.open=async function(){await v27MapOpen();if(!$('stock-map-canvas'))return;const mapApp=$('stock-map-metrics').closest('.map-app');document.querySelector('.map-policy')?.remove();$('v261-map-planning')?.remove();$('stock-map-vehicles').hidden=!this.data.vehicles.length&&!this.data.departed_pending.length;document.querySelector('.map-source-note')?.remove();document.querySelector('#v262-location-states')?.remove();document.querySelector('.map-zoom-toolbar')?.remove();for(const b of document.querySelectorAll('[data-map-region="P5"]'))b.textContent='临时堆存区';await V27.mapTools();const layout=mapApp.querySelector('.stock-map-layout'),rail=$('v271-map-labels');if(layout&&rail)layout.after(rail,$('stock-map-unmapped'),$('stock-map-vehicles'));};
const v27MapSelect=StockMap.select.bind(StockMap);StockMap.select=async function(id,page=1){await v27MapSelect(id,page);document.querySelector('.stock-map-layout')?.classList.add('v27-has-detail');const title=$('stock-map-detail')?.querySelector('h2');if(title&&/^P5/.test(title.textContent))title.textContent=title.textContent.replace(/^P5\s*/, '');const l=this.data.locations.find(l=>l.id===id);if(!l)return;};
const v27Loads=Flow.loads.bind(Flow);Flow.loads=async function(){await v27Loads();const link=document.createElement('a');link.className='button secondary';link.href='/outbounds/corrections';link.textContent='装车与正式出库更正';document.querySelector('#page-content .business-toolbar')?.append(link);};Flow.outbounds=Flow.loads;
const V27Lifecycle={async details(bundle){const section=document.createElement('section');section.className='v27-lifecycle';$('page-content').append(section);try{const h=await API.request('/bundles/'+encodeURIComponent(bundle.id)+'/lifecycle');section.innerHTML='<h2>捆包全生命周期</h2><p><span>库存归属状态</span>：'+({IN_STOCK:'账面在库',OUTBOUND:'已正式出库',ADJUSTED_OUT:'已授权调整移出'}[h.bundle.physical_status]||'待核查')+'</p><h3>装车及正式出库记录</h3><div class="business-table"><table><thead><tr><th>装车单</th><th>备货批号</th><th>车辆</th><th>实物离场时间</th><th>正式出库时间</th><th>净重（吨）</th><th>铅封号</th></tr></thead><tbody>'+h.loads.map(l=>'<tr><td>'+ (Business.can('load:read')?'<a data-no-i18n href="/outbounds/loads/'+l.id+'">'+esc(l.code)+'</a>':'<span data-no-i18n>'+esc(l.code)+'</span>')+'</td><td data-no-i18n>'+esc(l.lot_no||'—')+'</td><td data-no-i18n>'+esc(l.vehicle_no)+'</td><td data-no-i18n>'+esc(l.actual_departed_at||'—')+'</td><td data-no-i18n>'+esc(l.manager_at||'—')+'</td><td>'+Tonnes.format(l.net_weight)+'</td><td data-no-i18n>'+esc(l.seal_no||'—')+'</td></tr>').join('')+'</tbody></table></div><h3>关联更正及冲销</h3>'+h.corrections.map(c=>'<p>'+V27Reliability.kind(c.kind)+' · '+V27Reliability.status(c.status)+' · '+(Business.can('load:read')?'<a data-no-i18n href="/outbounds/corrections/'+c.id+'">'+esc(c.code)+'</a>':'<span data-no-i18n>'+esc(c.code)+'</span>')+' <span data-no-i18n>'+esc(c.reason)+'</span></p>').join('')+(Business.can('stocktake:read')?'<h3>关联盘点记录</h3>'+h.stocktakes.map(t=>'<p><a data-no-i18n href="/stocktaking/'+t.id+'">'+esc(t.code)+'</a> · '+V27Counts.phases[t.phase]+' · <span data-no-i18n>'+esc(t.remark)+'</span></p>').join(''):'');}catch(e){section.className='error';section.textContent=e.message;}}};
